-- Tabla unificada calificaciones (cursos 2021_22 a 2025_26)

DROP TABLE IF EXISTS calificaciones;
CREATE TABLE calificaciones (
    evaluacion TEXT,
    alumno TEXT,
    ensenanza TEXT,
    curso TEXT,
    contenido TEXT,
    bloque_contenido TEXT,
    nota_numerica TEXT,
    tipo_nota TEXT,
    anyo INTEGER
);

